import sys

sys.setrecursionlimit(20000)

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def getMaxSum(self, root: TreeNode) -> int:
        def dfs(node):
            if not node:
                return (0, 0)

            left_included, left_excluded = dfs(node.left)
            right_included, right_excluded = dfs(node.right)

            included = node.val + left_excluded + right_excluded
            excluded = max(left_included, left_excluded) + max(right_included, right_excluded)

            return (included, excluded)

        inc, exc = dfs(root)
        return max(inc, exc)

def main():
    lines = sys.stdin.read().strip().split('\n')
    if not lines:
        return

    n = int(lines[0])
    if n == 0:
        print(0)
        return

    adj = {}
    parent_map = {}

    idx = 1
    nodes_to_add = set()
    for _ in range(n - 1):
        parts = lines[idx].split()
        u, v = int(parts[0]), int(parts[1])
        idx += 1
        if u not in adj:
            adj[u] = []
        adj[u].append(v)
        if v not in adj:
            adj[v] = []
        adj[v].append(u)
        nodes_to_add.add(u)
        nodes_to_add.add(v)

    if n > 1:
        line_idx = idx
        while line_idx < len(lines) and not lines[line_idx].strip():
            line_idx += 1
        if line_idx < len(lines]:
            vals_line = lines[line_idx].split()
        else:
            vals_line = []
        if len(vals_line) != n:
            vals_line = [int(x) for x in lines[idx].split()]
        else:
            vals_line = [int(x) for x in lines[idx:n+idx]]
    else:
        vals_line = [int(lines[idx])] if idx < len(lines) else []

    if not vals_line:
        vals_line = [0] * n

    values = {i: vals_line[i-1] for i in range(1, n + 1)}

    if n == 1:
        print(values.get(1, 0))
        return

    queue = [1]
    visited = {1}
    children = {1: []}

    while queue:
        curr = queue.pop(0)
        if curr in adj:
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    children.setdefault(curr, []).append(neighbor)
                    children.setdefault(neighbor, [])
                    queue.append(neighbor)

    def build_tree(node_id):
        if node_id not in children or not children[node_id]:
            return TreeNode(values.get(node_id, 0))
        node = TreeNode(values.get(node_id, 0))
        kids = children[node_id]
        if kids:
            node.left = build_tree(kids[0])
            if len(kids) > 1:
                node.right = build_tree(kids[1])
        return node

    root_node = build_tree(1)
    sol = Solution()
    result = sol.getMaxSum(root_node)
    print(result)

if __name__ == "__main__":
    main()
